TAX_RATES = {"FR": 0.20, "DE": 0.19, "US": 0.0}

_cache = {}


def price_with_tax(price, country):
    key = (price, country)
    if key in _cache:
        return _cache[key]

    result = round(price * (1 + TAX_RATES[country]), 2)
    _cache[key] = result
    return result
